import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange != null ? dateRange.split("_") : new String[]{"2024-01-01", "2024-12-31"};

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildQuery(reportType, dates, department, sortCol);
            log.info("Executing report query for type=" + reportType + " dept=" + department);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {

                resp.setContentType("application/json");
                PrintWriter out = resp.getWriter();
                out.print("[\n");
                boolean first = true;
                ResultSetMetaData meta = rs.getMetaData();
                int colCount = meta.getColumnCount();

                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.print("  {");
                    for (int i = 1; i <= colCount; i++) {
                        if (i > 1) out.print(", ");
                        out.print("\"" + meta.getColumnLabel(i) + "\": ");
                        out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                    }
                    out.print("}");
                    first = false;
                }
                out.print("\n]");
            }
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportType, String[] dates, String department, String sortCol) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(reportType);
        sb.append(" WHERE created_at BETWEEN '").append(dates[0]).append("' AND '").append(dates[1]).append("'");

        if (department != null && !department.isEmpty()) {
            // Department comes from a dropdown in the UI
            sb.append(" AND department = '").append(department).append("'");
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            sb.append(" ORDER BY ").append(sortCol);
        }

        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.equals("sales") || type.equals("inventory") ||
               type.equals("hr") || type.equals("finance");
    }

    private String escapeJson(String val) {
        if (val == null) return "null";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
